package com.example.constitution

/**
 * All learning content for the app, kept as plain data so the app stays simple
 * and offline. Mirrors the content of the companion web app.
 */

data class Fact(val label: String, val value: String)

data class Part(
    val part: String,
    val title: String,
    val articles: String,
    val summary: String,
)

data class Schedule(
    val schedule: String,
    val title: String,
    val detail: String,
)

data class Article(
    val number: String,
    val title: String,
    val part: String,
    val tags: List<String>,
    val text: String,
    val explanation: String,
)

data class Flashcard(val front: String, val back: String)

data class QuizQuestion(
    val question: String,
    val options: List<String>,
    val answer: Int,
    val explain: String,
)

